const motionReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!motionReduced)document.documentElement.classList.add('js-motion');const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(el=>revealObserver.observe(el));
let scrollQueued=false,activeChapter=-1;
function onScroll(){scrollQueued=false;const y=scrollY,range=document.documentElement.scrollHeight-innerHeight;$('.page-progress').style.width=`${range?y/range*100:0}%`;const section=$('#engineering'),rect=section.getBoundingClientRect(),progress=Math.max(0,Math.min(.999,-rect.top/(section.offsetHeight-innerHeight)));const chapter=Math.min(2,Math.floor(progress*3));if(chapter!==activeChapter){activeChapter=chapter;$$('[data-chapter]').forEach(c=>c.classList.toggle('active',Number(c.dataset.chapter)===chapter));$$('[data-chapter-nav]').forEach(c=>c.classList.toggle('active',Number(c.dataset.chapterNav)===chapter));$('.engineering-progress').textContent=`0${chapter+1} — 03`;engineeringWatch.setExploded(chapter===1);engineeringWatch.setFace(chapter===2?'minimal':'performance');}if(!motionReduced){const world=$('#world').getBoundingClientRect();if(world.bottom>0&&world.top<innerHeight)$('#mountainImage').style.transform=`translateY(${(innerHeight/2-world.top-world.height/2)*.16}px)`;const hero=$('.hero-copy');if(y<1000){hero.style.transform=`translateY(${y*.13}px)`;hero.style.opacity=String(Math.max(.3,1-y/1000));$('.hero-watermark').style.transform=`translateY(${y*.25}px) rotate(-10deg)`;}}}
window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(onScroll)}},{passive:true});onScroll();
